theorem.raw:
\label{thm:recur}
Let the initial value $y_{0}$ and $v_{0}$, after the first $k$ steps without reseting the velocity, the iterative solution~(\ref{eqn:equiv_linear}) with the equivalent form~(\ref{eqn:equivtran}) has the form as below
\begin{equation}
\label{eqn:sol}
 \begin{pmatrix} (U_{1}^{T}y)_{k,i} \\ (U_{1}^{T}v)_{k,i} \end{pmatrix} =T_{i}^{k}  \begin{pmatrix} (U_{1}^{T}y)_{0,i} \\ (U_{1}^{T}v)_{0,i} \end{pmatrix} = \begin{pmatrix}
                    -\frac{\sin(k\theta_{i} - \phi_{i})}{\sin\phi_{i}} & \frac{\sin (k\theta_{i})}{\omega_{i}\sin\phi_{i}} \\
                    -\frac{\omega_{i} \sin (k\theta_{i})}{\sin\phi_{i}} & \frac{\sin(k\theta_{i} + \phi_{i})}{\sin\phi_{i}}
                    \end{pmatrix} \begin{pmatrix} (U_{1}^{T}y)_{0,i} \\ (U_{1}^{T}v)_{0,i} \end{pmatrix}
\end{equation}

lemma.raw:
\label{lem:equiv} The numerical scheme, shown as below
\begin{equation}
\label{eqn:equiv}
\begin{pmatrix}
       y_{k+1} \\
       v_{k+1}  
\end{pmatrix} = \begin{pmatrix}
       I -h^{2}A & hI \\
       -hA       & I 
\end{pmatrix}\begin{pmatrix}
       y_{k} \\
       v_{k}  
\end{pmatrix}
\end{equation}
is equivalent to the linearized symplectic-Euler scheme~(\ref{eqn:equiv_linear}), where we note that the linear transformation is 
\begin{equation}
\label{eqn:equivmatrix}
M
=\begin{pmatrix}
       I -h^{2}A & hI \\
       -hA       & I 
\end{pmatrix}.
\end{equation}

\label{lem:symmetric}
For every $2n\times 2n$ matrix $M$ in~(\ref{eqn:equivmatrix}), there exists the orthogonal transformation $U_{2n\times 2n}$ such that the matrix $M$ is similar as below
\begin{equation}
\label{eqn:equiveigen}
U^{T}MU = \begin{pmatrix} T_{1} & & & \\ &T_{2} & & \\ & &\ddots & \\ & & & T_{n} \end{pmatrix} 
\end{equation}
where $T_{i}$ $(i=1,\ldots, n)$ is $2\times 2$ matrix with the form 
\begin{equation}
\label{eqn:2by2}
T_{i} = \begin{pmatrix}
        1-\omega_{i}^{2}h^{2} & h \\
        -\omega_{i}^{2}h      & 1
        \end{pmatrix}
\end{equation}
where $\omega_{i}^{2}$ is the eigenvalue of the matrix $A$.

\label{lem:coorpro}
With the new coordinate in~(\ref{eqn:coortran}) for $0 < h\omega_{i} < \sqrt{2}$, we have 
\begin{equation}
\label{eqn:thetaphi}
2\phi_{i} + \theta_{i} = \pi
\end{equation}
and
\begin{equation}
\label{eqn:coorpro}
\left\{\begin{aligned}
       & \sin\theta_{i}  = \sin(2\phi_{i}) = h\omega_{i} \sin\phi_{i}\\
       & \sin(3\phi_{i}) = - \left(1 - h^{2}\omega_{i}^{2}\right)\sin\phi_{i}
       \end{aligned}\right. 
\end{equation}

\label{lem:equiv_express}
With the new coordinate in~(\ref{eqn:coortran}), the matrix $T_{i}$ ($i = 1, \ldots, n$) in~(\ref{eqn:2by2}) can expressed as below, 
\begin{equation}
\label{eqn:equiv_T}
T_{i} = \frac{1}{\omega_{i} \left(e^{-i\phi_{i}} - e^{i\phi_{i}}\right)}
           \begin{pmatrix}
           1 & 1 \\
           \omega_{i} e^{i\phi_{i}} & \omega_{i} e^{-i\phi_{i}}
           \end{pmatrix}\begin{pmatrix}
           e^{i\theta_{i}} & 0 \\
           0 & e^{-i\theta_{i}}
           \end{pmatrix}\begin{pmatrix}
           \omega_{i} e^{-i\phi_{i}} & -1 \\
           -\omega_{i} e^{i\phi_{i}} & 1
           \end{pmatrix}
\end{equation}

proof.raw:
$$
\begin{aligned}
&\begin{pmatrix}
I & -hI \\
0 &   I
\end{pmatrix}\begin{pmatrix}
       y_{k+1} \\
       v_{k+1}  
\end{pmatrix} = \begin{pmatrix}
I   &   0 \\
-hA &   I
\end{pmatrix}\begin{pmatrix}
       y_{k} \\
       v_{k}  
\end{pmatrix}
\Leftrightarrow \begin{pmatrix}
       y_{k+1} \\
       v_{k+1}  
\end{pmatrix} = \begin{pmatrix}
I-h^{2}A   &   hI \\
-hA &   I
\end{pmatrix}\begin{pmatrix}
       y_{k} \\
       v_{k}  
\end{pmatrix}
 \end{aligned}
$$

For the coordinate transformation in~(\ref{eqn:coortran}), we have
$$
T_{i} \begin{pmatrix}
       1 \\
       \omega_{i}e^{i\phi_{i}}
      \end{pmatrix} = \begin{pmatrix}
       1 \\
       \omega_{i}e^{i\phi_{i}}
      \end{pmatrix}  e^{i\theta_{i}}     \qquad \text{and}\qquad T_{i} \begin{pmatrix}
       1 \\
       \omega_{i}e^{-i\phi_{i}}
      \end{pmatrix} = \begin{pmatrix}
       1 \\
       \omega_{i}e^{-i\phi_{i}} 
      \end{pmatrix} e^{-i\theta_{i}}
$$
Hence,~(\ref{eqn:equiv_T}) is proved.

With Lemma~\ref{lem:equiv_express} and the coordinate transformation~(\ref{eqn:coortran}), we have
$$
\begin{aligned}
T_{i}^{k} & =\frac{1}{\omega_{i} \left(e^{-i\phi_{i}} - e^{i\phi_{i}}\right)}
           \begin{pmatrix}
           1 & 1 \\
           \omega_{i} e^{i\phi_{i}} & \omega_{i} e^{-i\phi_{i}}
           \end{pmatrix}
           \begin{pmatrix}
           e^{i\theta_{i}} & 0 \\
           0 & e^{-i\theta_{i}}
           \end{pmatrix}^{k} \begin{pmatrix}
           \omega_{i} e^{-i\phi_{i}} & -1 \\
           -\omega_{i} e^{i\phi_{i}} & 1
           \end{pmatrix}\\
                & =\frac{1}{\omega_{i} \left(e^{-i\phi_{i}} - e^{i\phi_{i}}\right)}
           \begin{pmatrix}
           1 & 1 \\
           \omega_{i} e^{i\phi_{i}} & \omega_{i} e^{-i\phi_{i}}
           \end{pmatrix} \begin{pmatrix}
           \omega e^{i(k\theta_{i} -\phi_{i})} & -e^{ik\theta_{i}} \\
           -\omega e^{-i(k\theta_{i} -\phi_{i})} & e^{-ik\theta_{i}}
           \end{pmatrix} \\
             & = \begin{pmatrix}
                    -\frac{\sin(k\theta_{i} - \phi_{i})}{\sin\phi_{i}} & \frac{\sin (k\theta_{i})}{\omega_{i}\sin\phi_{i}} \\
                    -\frac{\omega_{i} \sin (k\theta_{i})}{\sin\phi_{i}} & \frac{\sin(k\theta_{i} + \phi_{i})}{\sin\phi_{i}}
                    \end{pmatrix}  
\end{aligned}
$$
The proof is complete.

remark.raw:
In all the algorithms below, the symplectic Euler scheme can be taken place by the St\"{o}rmer-Verlet scheme, i.e.  
\begin{equation}
\label{eqn:symplectic_vertex}
\left\{\begin{aligned}
        & v_{k+1/2} = v_{k} - \frac{h}{2}\nabla f(x_{k}) \\
        & x_{k+1} = x_{k} + h v_{k + 1/2} \\
        & v_{k+1} = v_{k + 1/2} - \frac{h}{2} \nabla f(x_{k+1})
        \end{aligned}\right. 
\end{equation}
which works perfectly better than the symplectic scheme even if doubling step size and keep the left-right symmetry of the Hamiltonian system. The St\"{o}rmer-Verlet scheme is the natural discretization for 2nd-order ODE
\begin{equation}
\label{eqn:discrete}
x_{k+1} - 2x_{k} + x_{k-1} = -h^{2}\nabla f(x_{k})
\end{equation}
which is named as leap-frog scheme in PDEs. We remark that the discrete scheme~(\ref{eqn:discrete}) is different from the finite difference approximation by the forward Euler method to analyze the stability of 2nd ODE in~\citep{su2014differential}, since the momentum term is biased.

assumption.raw:
\label{ass:ill}
If the step size $h = \frac{1}{\sqrt{L}}$ for~(\ref{eqn:equiv_linear}), for the ill-conditioned eigenvalue $\omega_{i} \ll \sqrt{L}$, the coordinate variable can be approximated by the analytical solution as 
\begin{equation}
\label{eqn:approx}
\theta_{i} = h\omega_{i}, \qquad \text{and}\qquad\phi_{i} = \frac{\pi}{2}.
\end{equation}

algorithm.raw:
\begin{algorithmic}[1]
\State{Given a starting point $x_{0} \in \mathbf{dom}(f)$}
\State{Initialize the step length $h$, $\text{maxiter}$, and the velocity variable $v_{0} = 0$}
\State{Initialize the iterative variable $v_{iter} = v_{0}$}
\While{$\|\nabla f(x)\| > \epsilon$\;and\; $k < \text{maxiter}$}
\State{Compute $v_{iter}$ from the below equation in~(\ref{eqn:symplectic_euler})}
\If{$\|v_{iter}\| \leq \|v\|$}
         \State{$v = 0$}
      \Else
         \State{$v = v_{iter}$}
\EndIf

\State{Compute $x$ from the above equation in~(\ref{eqn:symplectic_euler})}
\State{$x_k = x$;}
\State{$f(x_{k}) = f(x)$;}
\State{$k = k + 1$;}
\EndWhile
\end{algorithmic}
\caption{Artifically Dissipating Energy Algorithm}
\label{alg:local}

\begin{algorithmic}[1]
\State{Given a starting point $x_{0} \in \mathbf{dom}(f)$}
\State{Initialize the step size $h$ and the maxiter}
\State{Initialize the velocity $v_{0}>0$ and compute $f(x_{0})$}
\State{Compute the velocity $x_1$ and $v_{1}$ from the equation~(\ref{eqn:symplectic_euler}), and compute $f(x_1)$ }
\For{$k= 1: n$}
      \State{Compute $x_{k+1}$ and $v_{k+1}$ from~(\ref{eqn:symplectic_euler})}
      \State{Compute $f(x_{k+1})$}
      \If{$\|v_{k}\| \geq \|v_{k+1}\|$ and $\|v_{k}\| \geq \|v_{k-1}\|$ }
      \State{Record the position $x_{k}$}
      \EndIf
\EndFor 
\end{algorithmic}
\caption{Energy Conservation Algorithm}
\label{alg:global}

\begin{algorithmic}[1]
\State{Given some starting points $x_{0,i} \in \mathbf{dom}(f)$ with $i = 1, \ldots,n$}
\State{Implement algorithm~\ref{alg:global} detecting the position there exists local minima, noted as $x_{j}$ with $j = 1, \ldots,m$}
\State{Implement algorithm~\ref{alg:local} from the result on line $2$ finding the local minima, noted as $x_{k}$ with $k=1,\ldots, l$}
\State{Comparison of $f(x_{k})$ with $k=1,\ldots,l$ to find global minima.}
\end{algorithmic}
\caption{Combined Algorithm}
\label{alg:combined}

