\begin{algorithmic}[1]
\State{Given some starting points $x_{0,i} \in \mathbf{dom}(f)$ with $i = 1, \ldots,n$}
\State{Implement algorithm~\ref{alg:global} detecting the position there exists local minima, noted as $x_{j}$ with $j = 1, \ldots,m$}
\State{Implement algorithm~\ref{alg:local} from the result on line $2$ finding the local minima, noted as $x_{k}$ with $k=1,\ldots, l$}
