       & \sin\phi_{i} = \sqrt{1 - \frac{h^{2}\omega_{i}^{2}}{4}}
       \end{aligned}\right.
\end{equation}
In order to make $\theta_{i}$ and $\phi_{i}$ located in $\left(0, \frac{\pi}{2}\right)$, we need to shrink to $0 < h\omega_{i} < \sqrt{2}$.

\begin{proof}
For the coordinate transformation in~(\ref{eqn:coortran}), we have
$$
T_{i} \begin{pmatrix}
       1 \\
       \omega_{i}e^{i\phi_{i}}
      \end{pmatrix} = \begin{pmatrix}
       1 \\
       \omega_{i}e^{i\phi_{i}}
      \end{pmatrix}  e^{i\theta_{i}}     \qquad \text{and}\qquad T_{i} \begin{pmatrix}
       1 \\
       \omega_{i}e^{-i\phi_{i}}
      \end{pmatrix} = \begin{pmatrix}
       1 \\
       \omega_{i}e^{-i\phi_{i}} 
      \end{pmatrix} e^{-i\theta_{i}}
$$
Hence,~(\ref{eqn:equiv_T}) is proved.
\end{proof}

\begin{proof}
With Lemma~\ref{lem:equiv_express} and the coordinate transformation~(\ref{eqn:coortran}), we have
$$
\begin{aligned}
