           -\omega e^{-i(k\theta_{i} -\phi_{i})} & e^{-ik\theta_{i}}
           \end{pmatrix} \\
             & = \begin{pmatrix}
                    -\frac{\sin(k\theta_{i} - \phi_{i})}{\sin\phi_{i}} & \frac{\sin (k\theta_{i})}{\omega_{i}\sin\phi_{i}} \\
                    -\frac{\omega_{i} \sin (k\theta_{i})}{\sin\phi_{i}} & \frac{\sin(k\theta_{i} + \phi_{i})}{\sin\phi_{i}}
                    \end{pmatrix}  
\end{aligned}
$$
