Firstly, the artificially dissipating energy algorithm based on~(\ref{eqn:symplectic_euler}) is proposed as below.
\begin{algorithm}[H]
\begin{algorithmic}[1]
\State{Given a starting point $x_{0} \in \mathbf{dom}(f)$}
\State{Initialize the step length $h$, $\text{maxiter}$, and the velocity variable $v_{0} = 0$}
\State{Initialize the iterative variable $v_{iter} = v_{0}$}
\While{$\|\nabla f(x)\| > \epsilon$\;and\; $k < \text{maxiter}$}
\State{Compute $v_{iter}$ from the below equation in~(\ref{eqn:symplectic_euler})}
\If{$\|v_{iter}\| \leq \|v\|$}
         \State{$v = 0$}
      \Else
         \State{$v = v_{iter}$}
\EndIf

\State{Compute $x$ from the above equation in~(\ref{eqn:symplectic_euler})}
\State{$x_k = x$;}
\State{$f(x_{k}) = f(x)$;}
\State{$k = k + 1$;}
\EndWhile
\end{algorithmic}
\caption{Artifically Dissipating Energy Algorithm}
\label{alg:local}
\end{algorithm}

\begin{rem}
In the actual algorithm~\ref{alg:local}, the codes in line $15$ and $16$ are not need in the while loop in order to  speed up the computation.
\end{rem}

Here,  the energy conservation algorithm based on~(\ref{eqn:symplectic_euler}) is proposed as below.
\begin{algorithm}[H]
\begin{algorithmic}[1]
\State{Given a starting point $x_{0} \in \mathbf{dom}(f)$}
\State{Initialize the step size $h$ and the maxiter}
\State{Initialize the velocity $v_{0}>0$ and compute $f(x_{0})$}
\State{Compute the velocity $x_1$ and $v_{1}$ from the equation~(\ref{eqn:symplectic_euler}), and compute $f(x_1)$ }
\For{$k= 1: n$}
      \State{Compute $x_{k+1}$ and $v_{k+1}$ from~(\ref{eqn:symplectic_euler})}
      \State{Compute $f(x_{k+1})$}
      \If{$\|v_{k}\| \geq \|v_{k+1}\|$ and $\|v_{k}\| \geq \|v_{k-1}\|$ }
      \State{Record the position $x_{k}$}
      \EndIf
\EndFor 
\end{algorithmic}
\caption{Energy Conservation Algorithm}
\label{alg:global}
\end{algorithm}
\begin{rem}
In the algorithm~\ref{alg:global}, we can set $v_{0} > 0$ such that the total energy large enough to climb up some high peak. Same as the algorithm~\ref{alg:local}, the function value $f(x)$ is not need in the while loop in order to  speed up the computation.
\end{rem}

